package in.anumati.platform.renewal; import java.time.*; import java.util.*; public record RenewalResponse(UUID id,UUID applicationId,UUID businessProfileId,String approvalCode,String approvalName,LocalDate validFrom,LocalDate validUntil,int reminderDays,RenewalStatus status,UUID sourceId,Instant updatedAt){static RenewalResponse from(RenewalRecord r){return new RenewalResponse(r.getId(),r.getApplication().getId(),r.getBusinessProfile().getId(),r.getApproval().getCode(),r.getApproval().getName(),r.getValidFrom(),r.getValidUntil(),r.getReminderDays(),r.getStatus(),r.getSource()==null?null:r.getSource().getId(),r.getUpdatedAt());}}
